class MachineState:
    def __init__(self, mid, cpu_cap, mem_cap):
        self.id = mid
        self.cpu_cap = cpu_cap
        self.mem_cap = mem_cap
        self.free_cpu = cpu_cap
        self.free_mem = mem_cap
        self.up = True
        self.running_tasks = []  # list of (task_id, finish_time)

    def add_task(self, task_id, finish_time):
        self.running_tasks.append((task_id, finish_time))

    def remove_task(self, task_id):
        t_info = tasks_info[task_id]
        # Find and remove
        for i, (tid, ft) in enumerate(self.running_tasks):
            if tid == task_id:
                del self.running_tasks[i]
                break

    def finish_tasks_at(self, time):
        finished = []
        still_running = []
        for tid, ft in self.running_tasks:
            if ft <= time:
                finished.append(tid)
            else:
                still_running.append((tid, ft))
        for tid in finished:
            t = tasks_info[tid]
            self.free_cpu += t["cpu"]
            self.free_mem += t["mem"]
        self.running_tasks = still_running
        return finished

    def can_fit(self, cpu_req, mem_req):
        return self.up and self.free_cpu >= cpu_req and self.free_mem >= mem_req

    def start_task(self, task_id):
        t = tasks_info[task_id]
        self.free_cpu -= t["cpu"]
        self.free_mem -= t["mem"]
        # We need to track when it finishes - this is handled in scheduling
        self.running_tasks.append((task_id, None))  # Will be set when we know finish time

    def set_finish_time(self, task_id, ft):
        for i, (tid, f) in enumerate(self.running_tasks):
            if tid == task_id:
                self.running_tasks[i] = (task_id, ft)
                break

