from collections import defaultdict

# Helper functions
def node_by_title(doc, title):
    for node in doc["nodes"]:
        if node["title"] == title:
            return node
    return None

def table_rows(node):
    rows = []
    for i, row in enumerate(node["table"]["rows"]):
        d = {}
        for j, col in enumerate(node["table"]["columns"]):
            d[col] = row[j]
