from collections import defaultdict

# State tracking
class Simulator:
    def __init__(self, tasks_info, machines):
        self.tasks = tasks_info
        self.machines = machines
        self.machine_state = {}
        for m in machines:
            self.machine_state[m] = {
                'free_cpu': machines[m]['cpu'],
                'free_mem': machines[m]['memory'],
                'running': [],  # (task, finish_time, cpu, mem)
                'down': False
            }
        self.queue = set()  # tasks waiting
        self.first_start = {}  # task -> first start time
        self.first_start_machine = {}  # task -> machine of first start
        self.submitted = set()
        self.finished = set()

    def get_queue_order(self):
        waiting = list(self.queue)
        waiting.sort(key=lambda t: (-self.tasks[t]['priority'], self.tasks[t]['submit_time'], t))
        return waiting

    def simulate(self):
        # Get all event times
        event_times = sorted(set(e['time'] for e in task_log if e['time'] <= 1200))

        events_by_time = defaultdict(list)
        for e in task_log:
            if e['time'] <= 1200:
                events_by_time[e['time']].append(e)

        for t in event_times:
            # Step 1: Finishes
            for e in events_by_time[t]:
                if e['event'] == 'finish':
                    m = e['machine']
                    task = e['task']
                    self.machine_state[m]['running'] = [(tk, ft, c, mem) for tk, ft, c, mem in self.machine_state[m]['running'] if tk != task]
                    self.machine_state[m]['free_cpu'] += e['cpu']
                    self.machine_state[m]['free_mem'] += e['memory']
                    self.finished.add(task)

            # Step 2: Failures
            for e in events_by_time[t]:
                if e['event'] == 'fail':
                    m = e['machine']
                    task = e['task']
                    self.machine_state[m]['running'] = [(tk, ft, c, mem) for tk, ft, c, mem in self.machine_state[m]['running'] if tk != task]
                    self.machine_state[m]['free_cpu'] += e['cpu']
                    self.machine_state[m]['free_mem'] += e['memory']
                    if task not in self.finished:
                        self.queue.add(task)

            # Step 3: Returns
            for m, info in self.machines.items():
                if info['returns_at'] is not None and info['returns_at'] == t:
                    self.machine_state[m]['down'] = False

