def check_at_time(time, time_label):
    active = [t for t in running if t['finish'] > time]

    machine_usage = {m: {'cpu': 0, 'mem': 0} for m in machines}
    for t in active:
        m = t['machine']
        machine_usage[m]['cpu'] += t['cpu']
        machine_usage[m]['mem'] += t['mem']

