    for m, cap in machines.items():
        if cap['status'] == 'down':
            continue
        free[m] = {
            'cpu': cap['cpu'] - machine_usage[m]['cpu'],
            'mem': cap['mem'] - machine_usage[m]['mem']
        }

    print(f"\n{time_label} - Free resources:")
